from itertools import product
from hypothesis import strategies as st


@st.composite
def gen(draw):
    n = draw(st.integers(3, 5))
    cands = [(s, t) for s in range(1, n + 1) for t in range(1, n + 1) if abs(s - t) > 1]
    pairs = draw(st.lists(st.sampled_from(cands), min_size=1, max_size=min(4, len(cands)), unique=True))
    m = len(pairs)
    q = draw(st.integers(1, 4))
    queries = []
    for _ in range(q):
        l = draw(st.integers(1, m))
        r = draw(st.integers(l, m))
        queries.append((l, r))
    lines = [f"{n} {m} {q}"]
    lines += [f"{s} {t}" for s, t in pairs]
    lines += [f"{l} {r}" for l, r in queries]
    return "\n".join(lines) + "\n"


def validate(inp):
    try:
        tokens = inp.split()
        if len(tokens) < 3:
            return False
        vals = [int(x) for x in tokens]
        n, m, q = vals[0], vals[1], vals[2]
        if not (3 <= n <= 4 * 10**5):
            return False
        if not (1 <= m <= 2 * 10**5):
            return False
        if not (1 <= q <= 2 * 10**5):
            return False
        if len(vals) != 3 + 2 * m + 2 * q:
            return False
        idx = 3
        pairs = set()
        for _ in range(m):
            s, t = vals[idx], vals[idx + 1]
            idx += 2
            if not (1 <= s <= n and 1 <= t <= n):
                return False
            if abs(s - t) <= 1:
                return False
            if (s, t) in pairs:
                return False
            pairs.add((s, t))
        for _ in range(q):
            l, r = vals[idx], vals[idx + 1]
            idx += 2
            if not (1 <= l <= r <= m):
                return False
        return True
    except Exception:
        return False


def _ok(n, persons, P):
    # P is a tuple with P[x-1] = potential of town x.
    # Rightward trip S<T: interior towns need P[x] > P[S].
    # Leftward trip S>T: interior towns need P[x] < P[S].
    # Both need P[S] == P[T].
    for s, t in persons:
        if P[s - 1] != P[t - 1]:
            return False
        if s < t:
            for x in range(s + 1, t):
                if not (P[x - 1] > P[s - 1]):
                    return False
        else:
            for x in range(t + 1, s):
                if not (P[x - 1] < P[s - 1]):
                    return False
    return True


def ref(inp):
    tokens = inp.split()
    vals = [int(x) for x in tokens]
    n, m, q = vals[0], vals[1], vals[2]
    idx = 3
    pairs = []
    for _ in range(m):
        pairs.append((vals[idx], vals[idx + 1]))
        idx += 2
    queries = []
    for _ in range(q):
        queries.append((vals[idx], vals[idx + 1]))
        idx += 2
    # Potentials can be compressed to ranks 0..n-1 without changing any
    # equality/strict-order relation, so enumerating range(n) is exhaustive.
    assignments = list(product(range(n), repeat=n))
    out = []
    for l, r in queries:
        sub = pairs[l - 1:r]
        feasible = any(_ok(n, sub, P) for P in assignments)
        out.append("Yes" if feasible else "No")
    return "\n".join(out)
