        return True
    except Exception:
        return False


def _feasible(N, persons):
    # Potentials P_1..P_N in {0..N-1} suffice (only order/equality constraints).
    # Road j weight = P_{j+1} - P_j. Person (S,T), a=min, b=max:
    #   P_a == P_b; interior P_t > P_a if S==a, interior P_t < P_a if S==b.
    for P in itertools.product(range(N), repeat=N):
        ok = True
        for S, T in persons:
            a, b = min(S, T), max(S, T)
            pa = P[a - 1]
            if P[b - 1] != pa:
                ok = False
                break
            for tw in range(a + 1, b):
                pt = P[tw - 1]
                if S == a:
                    if not pt > pa:
                        ok = False
                        break
                else:
                    if not pt < pa:
                        ok = False
                        break
            if not ok:
                break
        if ok:
            return True
    return False


